fn rolling_max(numbers: Vec<i32>) -> Vec<i32> {
    let mut result = Vec::with_capacity(numbers.len());
    // Initialize current_max to the smallest i32 value.
    // As we iterate, we'll update it to be the maximum seen so far.
    let mut current_max = i32::MIN;

    for x in numbers {
        // Update the running maximum
        current_max = current_max.max(x);
        // Push the current maximum onto the result
        result.push(current_max);
    }

    result
}

